input.command:
mkdir -p .cargo && cat > .cargo/config.toml <<'EOF'
[build]
target = "x86_64-pc-windows-gnu"

[target.x86_64-pc-windows-gnu]
linker = "x86_64-w64-mingw32-gcc"
ar = "x86_64-w64-mingw32-ar"
EOF
cat > src/main.rs <<'EOF'
use windows_sys::Win32::System::Threading::GetCurrentProcessId;
use windows_sys::Win32::UI::WindowsAndMessaging::{MessageBoxW, MB_ICONINFORMATION, MB_OK};

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

fn main() {
    let pid = unsafe { GetCurrentProcessId() };
    println!("Hello from Windows! PID = {pid}");

    let text = wide(&format!("Hello from Rust (PID {pid})"));
    let caption = wide("win_app");
    unsafe {
        MessageBoxW(
            std::ptr::null_mut(),
            text.as_ptr(),
            caption.as_ptr(),
            MB_OK | MB_ICONINFORMATION,
        );
    }
}
EOF
cat Cargo.toml; cargo check 2>&1 | tail -3; cargo build 2>&1 | tail -4; find ~/.cargo/registry/src -path '*windows_x86_64_gnu*' -name '*.a'

